function tuff_beatz_v14_business_command_setup(){
 $p=get_page_by_path('business-command');
 if(!$p){$id=wp_insert_post(array('post_title'=>'Business Command Center','post_name'=>'business-command','post_status'=>'publish','post_type'=>'page','post_content'=>''));if(!is_wp_error($id)&&$id)update_post_meta($id,'_wp_page_template','page-business-command.php');}
 else update_post_meta($p->ID,'_wp_page_template','page-business-command.php');
}
