function tuff_beatz_v14_business_command_assets(){if(!is_page('business-command'))return;$base=get_template_directory();$hub=$base.'/assets/css/portal-hubs.css';$lux=$base.'/assets/css/luxury-studio-os.css';$biz=$base.'/assets/css/business-command.css';if(file_exists($hub))wp_enqueue_style('tuff-beatz-portal-hubs',get_template_directory_uri().'/assets/css/portal-hubs.css',array('tuff-beatz-main'),filemtime($hub));if(file_exists($lux))wp_enqueue_style('tuff-beatz-luxury-studio-os',get_template_directory_uri().'/assets/css/luxury-studio-os.css',array('tuff-beatz-portal-hubs'),filemtime($lux));if(file_exists($biz))wp_enqueue_style('tuff-beatz-business-command',get_template_directory_uri().'/assets/css/business-command.css',array('tuff-beatz-luxury-studio-os'),filemtime($biz));}
add_action('wp_enqueue_scripts','tuff_beatz_v14_business_command_assets',84);
