function tuff_beatz_v14_project_business_summary(){
 $q=new WP_Query(array('post_type'=>'tb_request','post_status'=>'publish','posts_per_page'=>300,'orderby'=>'date','order'=>'DESC'));
 $r=array('project_count'=>count($q->posts),'quoted'=>0.0,'paid'=>0.0,'receivable'=>0.0,'deposit_due'=>0,'balance_due'=>0,'quotes_pending'=>0,'contracts_pending'=>0,'active_value'=>0.0,'completed_revenue'=>0.0,'receivable_projects'=>array());
 foreach($q->posts as $p){$id=$p->ID;$quote=function_exists('tuff_beatz_quote_data')?tuff_beatz_quote_data($id):array();$tot=function_exists('tuff_beatz_payment_totals')?tuff_beatz_payment_totals($id):array('total'=>0,'paid'=>0,'balance'=>0);$total=(float)($tot['total']??0);$paid=(float)($tot['paid']??0);$balance=(float)($tot['balance']??0);$r['quoted']+=$total;$r['paid']+=$paid;$r['receivable']+=$balance;$payment=(string)get_post_meta($id,'_tb_request_payment_status',true);if($payment==='Deposit due')$r['deposit_due']++;if($payment==='Balance due')$r['balance_due']++;if(!empty($quote)&&($quote['status']??'sent')!=='accepted')$r['quotes_pending']++;if(!empty($quote)&&!get_post_meta($id,'_tb_contract_acceptance',true))$r['contracts_pending']++;$status=(string)(get_post_meta($id,'_tb_request_status',true)?:'new');if($status==='completed')$r['completed_revenue']+=$paid;elseif($status!=='declined')$r['active_value']+=$total;if($balance>0)$r['receivable_projects'][]=array('id'=>$id,'title'=>$p->post_title,'client'=>get_post_meta($id,'_tb_request_artist',true)?:'Client','balance'=>$balance,'payment_status'=>$payment?:'Due','status'=>$status);}
 usort($r['receivable_projects'],function($a,$b){return $b['balance']<=>$a['balance'];});return $r;
}
function tuff_beatz_v149_financial_intelligence($pipeline=null,$business=null){
 if(!is_array($pipeline))$pipeline=function_exists('tuff_beatz_v14_pipeline_summary')?tuff_beatz_v14_pipeline_summary():array();if(!is_array($business))$business=tuff_beatz_v14_project_business_summary();$opps=function_exists('tuff_beatz_v14_opportunities')?tuff_beatz_v14_opportunities():array();$open=max(0,(int)($pipeline['open']??0));$won=max(0,(int)($pipeline['won']??0));$lost=max(0,(int)($pipeline['lost']??0));$closed=$won+$lost;$pipeline_value=(float)($pipeline['pipeline_value']??0);$weighted=(float)($pipeline['weighted_value']??0);$paid=(float)($business['paid']??0);$receivable=(float)($business['receivable']??0);$quoted=(float)($business['quoted']??0);$completed=(float)($business['completed_revenue']??0);$project_count=max(0,(int)($business['project_count']??0));$open_value=0.0;$won_value=0.0;$lost_value=0.0;$open_values=array();$won_values=array();$source=array();$service=array();foreach($opps as $o){$value=max(0,(float)($o['estimated_value']??0));$stage=$o['stage']??'new-lead';if($stage==='won'){$won_value+=$value;$won_values[]=$value;}elseif($stage==='lost')$lost_value+=$value;else{$open_value+=$value;$open_values[]=$value;}$src=trim((string)($o['source']??''))?:'Direct';$svc=trim((string)($o['service']??''))?:'Unspecified';if(!isset($source[$src]))$source[$src]=array('count'=>0,'value'=>0.0,'won'=>0);$source[$src]['count']++;$source[$src]['value']+=$value;if($stage==='won')$source[$src]['won']++;if(!isset($service[$svc]))$service[$svc]=array('count'=>0,'value'=>0.0,'won'=>0);$service[$svc]['count']++;$service[$svc]['value']+=$value;if($stage==='won')$service[$svc]['won']++;}uasort($source,function($a,$b){return $b['value']<=>$a['value'];});uasort($service,function($a,$b){return $b['value']<=>$a['value'];});$top_source=$source?array_key_first($source):'';$top_service=$service?array_key_first($service):'';$collection_base=$paid+$receivable;$collection_rate=$collection_base>0?($paid/$collection_base)*100:0;$quote_collection=$quoted>0?min(100,($paid/$quoted)*100):0;$conversion=$closed>0?($won/$closed)*100:0;$forecast_coverage=$receivable>0?$weighted/$receivable:($weighted>0?INF:0);$avg_open=$open?($open_value/$open):0;$avg_won=$won?($won_value/$won):0;$avg_project=$project_count?($paid/$project_count):0;$health=100;$signals=array();if($receivable>0&&$collection_rate<60){$health-=20;$signals[]='Collections need attention';}elseif($receivable>0&&$collection_rate<80){$health-=10;$signals[]='Receivables are elevated';}if($closed>=3&&$conversion<30){$health-=20;$signals[]='Closed-deal conversion is low';}elseif($closed>=3&&$conversion<50){$health-=10;$signals[]='Conversion can improve';}if($open>0&&$weighted<=0){$health-=15;$signals[]='Pipeline has no weighted forecast';}if($receivable>0&&is_finite($forecast_coverage)&&$forecast_coverage<1){$health-=10;$signals[]='Weighted pipeline is below receivables';}if(!$signals)$signals[]='Commercial indicators are stable';return array('health_score'=>max(0,min(100,$health)),'signals'=>$signals,'conversion_rate'=>$conversion,'collection_rate'=>$collection_rate,'quote_collection_rate'=>$quote_collection,'forecast_coverage'=>$forecast_coverage,'avg_open_deal'=>$avg_open,'avg_won_deal'=>$avg_won,'avg_project_collected'=>$avg_project,'open_value'=>$open_value,'won_value'=>$won_value,'lost_value'=>$lost_value,'top_source'=>$top_source,'top_source_data'=>$top_source?$source[$top_source]:array(),'top_service'=>$top_service,'top_service_data'=>$top_service?$service[$top_service]:array(),'source_performance'=>$source,'service_performance'=>$service,'closed_deals'=>$closed,'won_deals'=>$won,'lost_deals'=>$lost,'open_deals'=>$open,'pipeline_value'=>$pipeline_value,'weighted_value'=>$weighted,'paid'=>$paid,'receivable'=>$receivable,'completed_revenue'=>$completed);
}
function tuff_beatz_v14_opportunity_attention(){if(!function_exists('tuff_beatz_v14_opportunities'))return array();$out=array();$now=current_time('timestamp');foreach(tuff_beatz_v14_opportunities() as $o){if(in_array($o['stage'],array('won','lost'),true))continue;$score=0;$reason='';if($o['followup_at']&&strtotime($o['followup_at'])<=$now){$score=5;$reason='Follow-up due';}elseif($o['stage']==='deposit-due'){$score=4;$reason='Deposit due';}elseif($o['stage']==='contract'){$score=3;$reason='Contract decision';}elseif($o['stage']==='proposal'){$score=2;$reason='Proposal pending';}if($score)$out[]=array('id'=>$o['id'],'title'=>$o['title'],'contact'=>$o['contact_name']?:$o['contact_email'],'stage'=>$o['stage'],'reason'=>$reason,'value'=>$o['estimated_value'],'score'=>$score,'followup_at'=>$o['followup_at']);}usort($out,function($a,$b){return $b['score']<=>$a['score'];});return $out;}
function tuff_beatz_v14_stage_buckets(){if(!function_exists('tuff_beatz_v14_opportunity_stages'))return array();$b=array();foreach(tuff_beatz_v14_opportunity_stages() as $k=>$label)$b[$k]=array('label'=>$label,'count'=>0,'value'=>0.0,'weighted'=>0.0);foreach(function_exists('tuff_beatz_v14_opportunities')?tuff_beatz_v14_opportunities():array() as $o){if(!isset($b[$o['stage']]))continue;$b[$o['stage']]['count']++;$b[$o['stage']]['value']+=(float)$o['estimated_value'];$b[$o['stage']]['weighted']+=(float)$o['estimated_value']*((int)$o['probability']/100);}return $b;}
function tuff_beatz_v14_producer_business_link(){if(!is_page('producer-portal')||!is_user_logged_in()||!function_exists('tuff_beatz_is_producer_user')||!tuff_beatz_is_producer_user())return;?><script>document.addEventListener('DOMContentLoaded',function(){var a=document.querySelector('.tb-command-hero .tb-hub-actions');if(!a||a.querySelector('[data-tb-business-os]'))return;var x=document.createElement('a');x.className='btn btn-outline';x.href=<?php echo wp_json_encode(home_url('/business-command/'));?>;x.textContent='Business OS';x.setAttribute('data-tb-business-os','1');a.appendChild(x);});</script><?php }
add_action('wp_footer','tuff_beatz_v14_producer_business_link',8);
function tuff_beatz_v149_executive_intelligence(){if(!is_page('business-command')||!is_user_logged_in()||!function_exists('tuff_beatz_is_producer_user')||!tuff_beatz_is_producer_user())return;$pipeline=function_exists('tuff_beatz_v14_pipeline_summary')?tuff_beatz_v14_pipeline_summary():array();$business=tuff_beatz_v14_project_business_summary();$f=tuff_beatz_v149_financial_intelligence($pipeline,$business);$money=function($n){return function_exists('tuff_beatz_money')?tuff_beatz_money($n):'$'.number_format((float)$n,2);};$coverage=is_finite((float)$f['forecast_coverage'])?number_format((float)$f['forecast_coverage'],1).'×':'∞';ob_start();?><section class="tb-v149-intel"><div class="tb-v149-head"><div><small>EXECUTIVE INTELLIGENCE • V14.9</small><h3>Business Performance Signals</h3></div><div class="tb-v149-score"><span>COMMERCIAL HEALTH</span><strong><?php echo esc_html((string)$f['health_score']);?></strong><em>/100</em></div></div><div class="tb-v149-metrics"><article><small>DEAL CONVERSION</small><strong><?php echo esc_html(number_format((float)$f['conversion_rate'],1));?>%</strong><span><?php echo esc_html((string)$f['won_deals']);?> won / <?php echo esc_html((string)$f['closed_deals']);?> closed</span></article><article><small>COLLECTION RATE</small><strong><?php echo esc_html(number_format((float)$f['collection_rate'],1));?>%</strong><span><?php echo esc_html($money($f['paid']));?> collected</span></article><article><small>FORECAST COVERAGE</small><strong><?php echo esc_html($coverage);?></strong><span>weighted pipeline vs receivables</span></article><article><small>AVG OPEN DEAL</small><strong><?php echo esc_html($money($f['avg_open_deal']));?></strong><span><?php echo esc_html((string)$f['open_deals']);?> open opportunities</span></article><article><small>AVG WON DEAL</small><strong><?php echo esc_html($money($f['avg_won_deal']));?></strong><span><?php echo esc_html($money($f['won_value']));?> won value</span></article><article><small>AVG PROJECT COLLECTED</small><strong><?php echo esc_html($money($f['avg_project_collected']));?></strong><span>recorded payments per project</span></article></div><div class="tb-v149-bottom"><div class="tb-v149-signal"><small>EXECUTIVE SIGNAL</small><strong><?php echo esc_html((string)($f['signals'][0]??'Commercial indicators are stable'));?></strong><?php if(count($f['signals'])>1):?><span><?php echo esc_html(implode(' • ',array_slice($f['signals'],1)));?></span><?php endif;?></div><div class="tb-v149-leaders"><span><small>TOP LEAD SOURCE</small><strong><?php echo esc_html($f['top_source']?:'No data yet');?></strong><?php if($f['top_source']):?><em><?php echo esc_html($money($f['top_source_data']['value']??0));?> pipeline</em><?php endif;?></span><span><small>TOP SERVICE</small><strong><?php echo esc_html($f['top_service']?:'No data yet');?></strong><?php if($f['top_service']):?><em><?php echo esc_html($money($f['top_service_data']['value']??0));?> value</em><?php endif;?></span></div></div></section><?php $html=ob_get_clean();?><script>document.addEventListener('DOMContentLoaded',function(){var k=document.querySelector('.tb-biz-kpis');if(!k||document.querySelector('.tb-v149-intel'))return;var wrap=document.createElement('div');wrap.innerHTML=<?php echo wp_json_encode($html);?>;k.insertAdjacentElement('afterend',wrap.firstElementChild);});</script><?php }
add_action('wp_footer','tuff_beatz_v149_executive_intelligence',9);
